-- What supabase/loop_funnel.sql does, tried inside the rolled-back transaction
-- of a dry run on the live project: nothing here is kept. Only counts and
-- timings are printed, never a row of anybody's.
--
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js node --env-file=.env \
--     tools/apply_sql.mjs supabase/loop_funnel.sql --dry --try=tools/loop_funnel_try.sql --table=insights_visits
--
-- The accounts are people's ids from auth.users (none @resend.dev), with no
-- hash: the database has no VIEW_SECRET, so no hash is joined to an id here
-- (heard back, the kept shares and Claude's days read 0; the owner is not
-- told apart). The steps are api/_loop.js's LOOP as of loopmetrics.
--
-- Each statement is on one line: the dry run splits at a semicolon that
-- ends a line.
-- The function: the server's alone, a definer's, with an empty search path; and no table of its own left behind.
select p.proname as function_name, has_function_privilege('anon', p.oid, 'execute') as anon_runs, has_function_privilege('authenticated', p.oid, 'execute') as signed_in_runs, has_function_privilege('service_role', p.oid, 'execute') as server_runs, p.prosecdef as definer, p.proconfig as config from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'insights_loop';
-- The live loop over the last 30 days and the 30 before, people's rows, everyone but nobody told apart: each step's person-days, where each stopped, built.
with a as (select coalesce(jsonb_agg(jsonb_build_object('h', null, 'id', u.id, 'plan', 'free')), '[]'::jsonb) as list from auth.users u where u.email !~* '@resend\.dev$'), s as (select '[["discovered","site","view","/"],["discovered","site","view","/gallery"],["discovered","site","view","/library"],["discovered","site","view","/library/set/:n"],["discovered","site","view","/library/:id"],["discovered","site","view","/m/:id"],["discovered","site","view","/m/:id/v/:n"],["discovered","site","view","/talk"],["discovered","site","view","/talk/b/:board"],["discovered","site","view","/talk/t/:n"],["discovered","site","view","/u/:handle"],["discovered","site","view","/c/:id"],["discovered","site","view","/collections"],["discovered","site","view","/builds"],["discovered","site","view","/feed"],["discovered","site","view","/challenge"],["opened","site","view","/m/:id"],["opened","site","view","/m/:id/v/:n"],["opened","studio","view","/app"],["opened","studio","panel","step_playback"],["changed","studio","part","placed"],["changed","studio","milestone","first_part"],["shared","studio","press","share_publish"],["shared","site","act","share.post"],["shared","site","act","people.comment"],["shared","site","act","people.reply"],["shared","site","act","people.photo"],["shared","site","act","people.talk_start"],["shared","site","act","people.talk_reply"],["shared","site","act","people.enter"]]'::jsonb as steps), r as materialized (select public.insights_loop((now() at time zone 'utc')::date - 29, (now() at time zone 'utc')::date, false, '{}'::jsonb, a.list, s.steps) as x from a, s) select x->'range' as range_read, x->'this'->'people' as people, x->'this'->'signed_in' as signed_in, x->'this'->'steps' as steps, x->'this'->'stopped' as stopped, x->'this'->'built' as built, x->'this'->'kept_days' as kept_days, x->'before'->'people' as before_people, x->'before'->'steps' as before_steps, x->'before'->'built' as before_built, x->'before'->'kept_days' as before_kept_days from r;
-- The same read's names with anybody at them, this range: what each step counted.
with a as (select coalesce(jsonb_agg(jsonb_build_object('h', null, 'id', u.id, 'plan', 'free')), '[]'::jsonb) as list from auth.users u where u.email !~* '@resend\.dev$'), s as (select '[["discovered","site","view","/"],["discovered","site","view","/gallery"],["discovered","site","view","/library"],["discovered","site","view","/library/set/:n"],["discovered","site","view","/library/:id"],["discovered","site","view","/m/:id"],["discovered","site","view","/m/:id/v/:n"],["discovered","site","view","/talk"],["discovered","site","view","/talk/b/:board"],["discovered","site","view","/talk/t/:n"],["discovered","site","view","/u/:handle"],["discovered","site","view","/c/:id"],["discovered","site","view","/collections"],["discovered","site","view","/builds"],["discovered","site","view","/feed"],["discovered","site","view","/challenge"],["opened","site","view","/m/:id"],["opened","site","view","/m/:id/v/:n"],["opened","studio","view","/app"],["opened","studio","panel","step_playback"],["changed","studio","part","placed"],["changed","studio","milestone","first_part"],["shared","studio","press","share_publish"],["shared","site","act","share.post"],["shared","site","act","people.comment"],["shared","site","act","people.reply"],["shared","site","act","people.photo"],["shared","site","act","people.talk_start"],["shared","site","act","people.talk_reply"],["shared","site","act","people.enter"]]'::jsonb as steps), r as materialized (select public.insights_loop((now() at time zone 'utc')::date - 29, (now() at time zone 'utc')::date, false, '{}'::jsonb, a.list, s.steps) as x from a, s) select e->>'step' as step, e->>'surface' as surface, e->>'kind' as kind, e->>'name' as name, (e->>'people')::int as people from r, jsonb_array_elements(r.x->'this'->'acts') e where (e->>'people')::int > 0;
-- How long the read takes over 90 days and the 90 before, every account of people's listed, twice (the second warm); and its size.
with a as (select coalesce(jsonb_agg(jsonb_build_object('h', null, 'id', u.id, 'plan', 'free')), '[]'::jsonb) as list from auth.users u where u.email !~* '@resend\.dev$'), t as materialized (select clock_timestamp() as t0 from a), r as materialized (select public.insights_loop((now() at time zone 'utc')::date - 89, (now() at time zone 'utc')::date, false, '{}'::jsonb, a.list, '[["discovered","site","view","/"],["opened","site","view","/m/:id"],["changed","studio","part","placed"],["shared","site","act","people.comment"]]'::jsonb) as x from a, t) select octet_length(r.x::text) as bytes, round(extract(epoch from clock_timestamp() - t.t0) * 1000) as ms from r, t;
with a as (select coalesce(jsonb_agg(jsonb_build_object('h', null, 'id', u.id, 'plan', 'free')), '[]'::jsonb) as list from auth.users u where u.email !~* '@resend\.dev$'), t as materialized (select clock_timestamp() as t0 from a), r as materialized (select public.insights_loop((now() at time zone 'utc')::date - 89, (now() at time zone 'utc')::date, false, '{}'::jsonb, a.list, '[["discovered","site","view","/"],["opened","site","view","/m/:id"],["changed","studio","part","placed"],["shared","site","act","people.comment"]]'::jsonb) as x from a, t) select octet_length(r.x::text) as bytes, round(extract(epoch from clock_timestamp() - t.t0) * 1000) as ms from r, t;
-- The checks' own over 90 days: a busier set of rows than people's today.
with a as (select coalesce(jsonb_agg(jsonb_build_object('h', null, 'id', u.id, 'plan', 'free')), '[]'::jsonb) as list from auth.users u where u.email ~* '@resend\.dev$'), t as materialized (select clock_timestamp() as t0 from a), r as materialized (select public.insights_loop((now() at time zone 'utc')::date - 89, (now() at time zone 'utc')::date, true, '{}'::jsonb, a.list, '[["discovered","site","view","/"],["opened","site","view","/m/:id"],["changed","studio","part","placed"],["shared","site","act","people.comment"]]'::jsonb) as x from a, t) select r.x->'this'->'people' as checks_people, octet_length(r.x::text) as bytes, round(extract(epoch from clock_timestamp() - t.t0) * 1000) as ms from r, t;
-- Nothing of its own outlives the read.
select count(*) as loop_tables_left from pg_tables where tablename like 'loop\_%' and schemaname not like 'pg_temp%';
